fn less(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    // Create a new vector to hold the results
    let mut result = Vec::with_capacity(a.len());
    
    // Iterate over the elements of both arrays
    for (x, y) in a.iter().zip(b.iter()) {
        // Push the comparison result into the result vector
        result.push(x < y);
    }
    
    result
}